WebLink.url:
{!REQUIRESCRIPT("/flow/Bulk_Update_On_Opportunity")}
var selectedIds = {!GETRECORDIDS($ObjectType.Opportunity)};
if (selectedIds.length === 0) {
alert("Please select at least one record.");
} else {
var flowUrl = "/flow/Bulk_Update_On_Opportunity?ids=" + selectedIds.join(",");
window.open(flowUrl, "_blank");
}
